const paths={arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',person:'M8 7a4 4 0 1 0 8 0 4 4 0 0 0-8 0M4 21v-3a8 8 0 0 1 16 0v3',couple:'M4 7a3 3 0 1 0 6 0 3 3 0 0 0-6 0m10 0a3 3 0 1 0 6 0 3 3 0 0 0-6 0M1 21v-4a6 6 0 0 1 12 0v4m0-7a6 6 0 0 1 10 3v4',family:'M3 6a3 3 0 1 0 6 0 3 3 0 0 0-6 0m12 0a3 3 0 1 0 6 0 3 3 0 0 0-6 0M1 20v-5a5 5 0 0 1 7-4m8 0a5 5 0 0 1 7 4v5M10 13a2 2 0 1 0 4 0 2 2 0 0 0-4 0m-2 9v-3a4 4 0 0 1 8 0v3',group:'M9 5a3 3 0 1 0 6 0 3 3 0 0 0-6 0M6 20v-4a6 6 0 0 1 12 0v4M1 9a2 2 0 1 0 4 0 2 2 0 0 0-4 0m18 0a2 2 0 1 0-4 0 2 2 0 0 0 4 0M1 21v-5a3 3 0 0 1 4-3m14 0a3 3 0 0 1 4 3v5',home:'m3 10 9-8 9 8M5 9v13h14V9M9 22v-8h6v8',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Zm-11 0a3 3 0 1 0 6 0 3 3 0 0 0-6 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',bed:'M2 19V9h20v10M2 15h20M5 9V5h14v4M2 19v3m20-3v3M12 5v4',bath:'M3 12h18v3a6 6 0 0 1-6 6H9a6 6 0 0 1-6-6v-3ZM5 12V5a3 3 0 0 1 6 0M6 21v2m12-2v2',area:'M3 9V3h6m6 0h6v6m0 6v6h-6m-6 0H3v-6',map:'m2 5 6-3 8 3 6-3v17l-6 3-8-3-6 3V5Zm6-3v17m8-14v17',leaf:'M20 3C7 1 0 12 8 18s15-3 12-15ZM5 22 17 7',waves:'M2 6q3-4 6 0t6 0 8 0M2 12q3-4 6 0t6 0 8 0M2 18q3-4 6 0t6 0 8 0',coffee:'M3 3h13v12a5 5 0 0 1-5 5H8a5 5 0 0 1-5-5V3Zm13 2h2a4 4 0 0 1 0 8h-2M1 23h20',walk:'M12 3a2 2 0 1 0 4 0 2 2 0 0 0-4 0M7 21l4-8 3 3v6M4 12l5-5 4 1 2 5h5m-9 0 2-5',sun:'M8 12a4 4 0 1 0 8 0 4 4 0 0 0-8 0M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',sparkle:'m12 1 3 8 8 3-8 3-3 8-3-8-8-3 8-3Z',car:'m3 9 2-6h14l2 6M2 9h20v9H2V9Zm3 4h2m10 0h2M4 18v3m16-3v3',bus:'M5 3h14v15H5V3Zm0 7h14M8 14h1m6 0h1M7 18v3m10-3v3M8 1h8',bolt:'m13 1-9 13h7l-1 9 10-14h-8l1-8Z',work:'M3 6h18v15H3V6Zm5 0V2h8v4M3 11l9 4 9-4M12 15v3',school:'m1 8 11-6 11 6-11 6L1 8Zm4 3v6q7 6 14 0v-6M23 8v9',clock:'M3 12a9 9 0 1 0 18 0 9 9 0 0 0-18 0Zm9-5v6l4 2',coin:'M3 12a9 9 0 1 0 18 0 9 9 0 0 0-18 0Zm13-5H9v10h7M7 10h7M7 14h7',sliders:'M3 6h6m6 0h6M3 18h12m4 0h2M9 3v6m6 6v6',share:'M8 9 16 5M8 15l8 4M2 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0m14-8a3 3 0 1 0 6 0 3 3 0 0 0-6 0m0 16a3 3 0 1 0 6 0 3 3 0 0 0-6 0',plus:'M12 4v16M4 12h16',minus:'M4 12h16',building:'M5 22V3h10v19m0-14h5v14M2 22h21M8 7h3M8 11h3M8 15h3M8 19h3',compare:'M8 3v18m8-18v18M3 7h10m-2 10h10',info:'M3 12a9 9 0 1 0 18 0 9 9 0 0 0-18 0Zm9-2v7m0-11v1',lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v12H4V10Zm8 5v3'};
function icon(name,cls=''){if(!['arrow','back','check','close','plus','minus','sliders','info','lock'].includes(name))return dimensionalIcon(name,paths[name]||paths.sparkle,cls);return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.sparkle}"/></svg>`;}
let profile=blankProfile();try{profile=restoreProfile(JSON.parse(sessionStorage.getItem('nexus-link-profile')||'null'));}catch{}
let superFavorites=new Set();try{const saved=JSON.parse(localStorage.getItem('nexus-link-super-favorites')||'[]');if(Array.isArray(saved))superFavorites=new Set(saved.filter(x=>typeof x==='string'));}catch{}
let intentMarket='';try{intentMarket=sessionStorage.getItem('nexus-link-intent-market')||'';}catch{}
const state={step:0,profile,intentMarket,results:null,favorites:new Set(),superFavorites,compare:new Set(),week:'this',category:'all',view:'list',request:0,photos:{},commercialTypes:[]};
let lastSearch=null;try{const saved=JSON.parse(sessionStorage.getItem('nexus-link-last-search')||'null');if(saved?.profile)lastSearch={profile:restoreProfile(saved.profile),filters:restoreSearchFilters(saved.filters)};}catch{}
const searchCache=createSearchCache(()=>adapter.getMatches(candidateProfile(state.profile)));
const stepNames=['Your people','Your home','Your everyday','Your priorities'];
const categories={best:'Best Fit',alternative:'Smart Alternatives',compromise:'Compromise Options',outside:'Outside Your Brief'};
const mapExperience=createMapExperience({developments:DEVELOPMENTS,getActivities:anchor=>adapter.getActivities(anchor),getProfile:()=>state.profile,onSearchBack:clearActiveSearch,onHome:()=>{history.replaceState(null,'','#profile');renderProfile();updateHeader();window.scrollTo({top:0,behavior:'instant'});attachMapDock();},onDevelopment:id=>location.hash=`development/${encodeURIComponent(id)}`,onProperty:revealPropertyFromMap,renderCards:items=>items.map(card).join(''),onCardsReady:bindGalleries,getFavorites:()=>state.favorites,getSuperFavorites:()=>state.superFavorites,onLocations:labels=>{state.profile.requirements.locations.value=labels;persist();placesControl?.render();},onPriorityLocations:labels=>{state.profile.favoriteTowns=labels;persist();placesControl?.render();},getSearchProperties:async()=> (await getCandidates()).properties});
function mapDock(){return `<div class="map-dock-wrap"><div class="map-dock" data-map-dock></div><button class="map-dock-open" data-action="reveal-map" aria-label="Explore the Nexus Map"><span>YOUR WORLD, IN VIEW</span><b>Explore the Nexus Map ${icon('arrow')}</b></button><span class="map-dock-corner">3D</span></div>`;}
function mapMarketEntry(){const choices=[['sales','Buy','building'],['longlets','Longlet','home'],['stays','Shortstay','bed'],['commercials','Commercials','work']];return `<section class="map-market-entry"><span>WHAT ARE YOU LOOKING FOR?</span><div>${choices.map(([market,label,symbol])=>`<button data-action="map-market" data-market="${market}" aria-pressed="${state.intentMarket===market}" class="${state.intentMarket===market?'active':''}">${icon(symbol)}<strong>${label}</strong></button>`).join('')}</div></section>`;}
function attachMapDock(){if(document.body.dataset.page==='profile'){const foot=$('.intro-foot');if(foot&&!$('[data-map-dock]'))foot.insertAdjacentHTML('beforebegin',mapDock()+mapMarketEntry());}else if(document.body.dataset.page==='results'){const teaser=$('.map-teaser');if(teaser&&!$('[data-map-dock]'))teaser.innerHTML=`<div class="map-teaser-top"><span>ANOTHER PERSPECTIVE</span>${icon('map')}</div>${mapDock()}<p>Your world is closer than you think.<br>Open the map to explore it.</p>`;}if(document.body.dataset.page==='property'&&!document.querySelector('.property-map-dock')){const host=document.createElement('div');host.className='property-map-dock';host.innerHTML=mapDock();document.querySelector('.detail-page').append(host);host.querySelector('.map-dock-open').setAttribute('aria-label','Return to this place on the map');host.querySelector('.map-dock-open>b').innerHTML='Back to this place '+icon('arrow');}mapExperience.refresh(state.displayProperties||[]);if(document.body.dataset.page==='property'&&state.currentProperty){const p=state.currentProperty;mapExperience.previewPlace({id:p.developmentId||p.id,kind:p.developmentId?'development':'property',developmentId:p.developmentId,coordinates:p.coordinates});}}
function persist(){try{sessionStorage.setItem('nexus-link-profile',JSON.stringify(state.profile));}catch{}state.results=null;searchCache.invalidate();}
function clearActiveSearch(filters){const reset=resetSearch(state.profile,filters,lastSearch);lastSearch=reset.lastSearch;state.profile=reset.profile;state.step=0;state.week='this';state.category='all';state.commercialTypes=[];state.displayProperties=[];state.currentProperty=null;state.request++;persist();try{sessionStorage.setItem('nexus-link-last-search',JSON.stringify(lastSearch));}catch{}toast('Search cleared. Your last search is saved here.');}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function photoUrl(key){return ['coastal','urban','terrace'].includes(key)?`./assets/${key}.png`:safeUrl(key);}
function safeUrl(value){try{const u=new URL(value,location.href);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function imageTag(key,alt,cls='',lazy=true){return `<img class="${cls}" src="${esc(photoUrl(key))}" alt="${esc(alt)}" ${lazy?'loading="lazy"':''} decoding="async">`;}
function demoNote(){return adapter.mode==='demo'?'<span class="demo-pill">CONCEPT PREVIEW · DEMO HOMES</span>':adapter.mode==='argus'?`<span class="demo-pill">2906 INVENTORY · ${state.results?.mode==='live'?'LIVE':state.results?'SNAPSHOT':'CONNECTING'}</span>`:'';}
function option(value,label,selected){return `<option value="${esc(value)}" ${selected===value?'selected':''}>${esc(label)}</option>`;}
const preferenceLevels=['any','nice','important','required'];
function importance(key,label=key){const r=state.profile.requirements[key],level=preferenceLevels.indexOf(r.importance);return `<label class="importance-slider"><span>${IMPORTANCE.find(x=>x[0]===r.importance)?.[1]||'Important'}</span><input type="range" min="0" max="3" step="1" value="${Math.max(0,level)}" data-importance="${key}" aria-label="Importance of ${esc(label)}" aria-valuetext="${IMPORTANCE.find(x=>x[0]===r.importance)?.[1]||'Important'}"></label>`;}
function rangeControl(key,value,{max=5,step=1,kind='requirement',label=key,unit='',maxLabel,anchor}={}){
 const budget=key==='budget',numeric=budget?budgetPosition(value):value??0;const openEnded=budget&&state.profile.requirements.budget.openEnded===true;
 if(budget){max=100;step=1;maxLabel='€10,000+';}
 const display=budget?budgetLabel(value,openEnded):value===null||value===undefined?'Keep open':`${value}${unit}`;
 return `<div class="range-control"><div class="range-value"><output>${display}</output><span>${budget?'PER MONTH':'DRAG TO CHOOSE'}</span></div><input type="range" min="0" max="${max}" step="${step}" value="${Math.min(max,numeric)}" data-range="${key}" data-range-kind="${kind}" ${anchor===undefined?'':`data-range-anchor="${anchor}"`} data-range-unit="${unit}" aria-label="${esc(label)}" aria-valuetext="${esc(display)}" style="--range-fill:${Math.min(max,numeric)/max*100}%"><div class="range-scale ${budget?'budget-scale':''}"><span>${budget?'€0':'Open'}</span>${budget?'<span class="budget-midpoint">€2,500</span>':''}<span>${maxLabel||`${max}${unit}`}</span></div></div>`;
}
function toggleRange(key,label,description){const active=state.profile.requirements[key].value===true;return `<div class="preference-toggle"><div><strong>${label}</strong><p>${description}</p></div><label class="toggle-slider"><input type="range" min="0" max="1" step="1" value="${active?1:0}" data-toggle-range="${key}" aria-label="${label}" aria-valuetext="${active?'Yes':'Keep open'}"><span>${active?'Yes':'Open'}</span></label></div>`;}
function requirementField(key,label,input){return `<div class="requirement"><div class="field-head"><label for="req-${key}">${label}</label>${importance(key,label)}</div>${input}</div>`;}
function reqSelect(key,choices,placeholder='Keep open'){const value=state.profile.requirements[key].value;return `<select id="req-${key}" data-requirement="${key}">${option('',placeholder,value===null?'':value)}${choices.map(([v,l])=>option(String(v),l,value===null?'':String(value))).join('')}</select>`;}
function chips(key,options){return `<div class="choice-row">${options.map(([value,label,i])=>`<button type="button" class="choice ${state.profile[key]===value?'selected':''}" data-profile="${key}" data-value="${value}" aria-pressed="${state.profile[key]===value}">${i?icon(i):''}${label}</button>`).join('')}</div>`;}
let profileObserver,placesControl;
function installPlaces(){const host=document.querySelector('.location-choices');if(!host)return;mapExperience.setLocations(state.profile.requirements.locations.value);placesControl=createPlacesSelector(host,{showOffers:false,getZones:()=>mapExperience.getFilters().drawnAreas,onZones:zones=>mapExperience.setDrawnAreas(zones),getHomes:()=>mapExperience.getMatchingHomes(),getFavorites:()=>state.favorites,getSuperFavorites:()=>state.superFavorites,getPriorityLabels:()=>state.profile.favoriteTowns||[],onPriorityChange:labels=>{state.profile.favoriteTowns=labels;persist();mapExperience.setLocations(state.profile.requirements.locations.value);},onShowMap:scope=>mapExperience.showZoneMatches(scope),getLabels:()=>state.profile.requirements.locations.value,onChange:labels=>{state.profile.requirements.locations.value=labels;state.profile.favoriteTowns=(state.profile.favoriteTowns||[]).filter(label=>labels.includes(label));persist();mapExperience.setLocations(labels);},onMap:()=>{mapExperience.setLocations(state.profile.requirements.locations.value);mapExperience.exploreLocations();}});}
function scrollProfileTo(step){state.step=Math.max(0,Math.min(3,step));const panel=document.querySelector(`[data-scroll-step="${state.step}"]`);panel?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});panel?.querySelector('h2')?.focus({preventScroll:true});}
function renderProfile(){
 const previousScroll=window.scrollY;profileObserver?.disconnect();
 $('#content').innerHTML=profileMarkup(0);
 const workspace=document.querySelector('.profile-workspace'),first=workspace.querySelector('.scorecard');
 first.dataset.scrollStep='0';first.classList.add('scroll-scorecard');
 for(let i=1;i<4;i++){const template=document.createElement('template');template.innerHTML=profileMarkup(i);const card=template.content.querySelector('.scorecard');card.dataset.scrollStep=String(i);card.classList.add('scroll-scorecard');workspace.insertBefore(card,workspace.querySelector('.below-card'));}
 document.querySelector('.profile-layout').classList.add('scroll-profile');
 const picker=document.querySelector('[data-profile-types]');if(picker)bindTypePicker(picker,()=>state.profile.requirements.propertyType.value,value=>{state.profile.requirements.propertyType.value=value;persist();});
 profileObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;state.step=Number(entry.target.dataset.scrollStep);entry.target.classList.add('has-arrived');document.querySelectorAll('.profile-steps [data-step]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.step)===state.step);b.classList.toggle('done',Number(b.dataset.step)<state.step);if(Number(b.dataset.step)===state.step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});document.body.style.setProperty('--chapter-progress',String(state.step/3));}},{rootMargin:'-15% 0px -55% 0px',threshold:0});
 document.querySelectorAll('[data-scroll-step]').forEach(panel=>profileObserver.observe(panel));
 attachMapDock();const reel=document.querySelector('.property-reel');if(reel)installPropertyReel(reel,{load:getResults,photoUrl,onSelect:id=>openMap({kind:'property',id})});
 if(lastSearch)document.querySelector('.intro-foot').insertAdjacentHTML('beforebegin',`<div class="last-search"><span><strong>Your last search</strong><small>Saved here. No filters applied automatically.</small></span><button type="button" data-action="restore-search">Restore ↗</button></div>`);
 installPlaces();window.scrollTo({top:previousScroll,behavior:'instant'});
}
function profileMarkup(s){
document.body.dataset.page='profile';
 return `<div class="profile-layout"><section class="intro"><div class="eyebrow"><span class="tiny-star">✦</span> A MORE CONNECTED YOU</div><h1>Your life.<br>Your place.<br><span class="headline-last">Connected.</span></h1><p class="intro-copy">More than the right home.<br>The right everyday.</p><div class="hero-photo"><div class="hero-image film-fed-image">${['coastal','urban','terrace'].map((key,i)=>`<div class="hero-scene scene-${i}">${imageTag(key,'Illustrative Mediterranean home interior','',false)}</div>`).join('')}</div><div class="hero-caption"><span>${icon('pin')} MALTA</span><span>A BRIGHTER EVERYDAY ${icon('arrow')}</span></div><span class="image-label">ILLUSTRATIVE IMAGE</span></div><div class="property-reel" aria-label="A moving collection of homes"></div><div class="intro-foot"><span>01 / YOUR NEXT CHAPTER</span><span class="coordinates">35.8992° N &nbsp; 14.5141° E</span></div></section>
 <section class="profile-workspace" aria-label="Living profile"><div class="workspace-top"><span>THE LIVING SCORECARD</span><span>0${s+1}<i> / 04</i></span></div><nav class="profile-steps" aria-label="Profile steps">${stepNames.map((name,i)=>`<button class="${i===s?'active':''} ${i<s?'done':''}" data-action="step" data-step="${i}" ${i===s?'aria-current="step"':''}><span>${i<s?icon('check'):String(i+1).padStart(2,'0')}</span><small>${name}</small></button>`).join('')}</nav><div class="scorecard"><div class="scorecard-inner"><div class="card-kicker">${['IT STARTS WITH YOU','SPACE FOR YOUR LIFE','TIME FOR WHAT MATTERS','MAKE IT YOUR OWN'][s]}<span>✦</span></div><h2 tabindex="-1" id="step-title-${s}">${['Who’s coming home?','What feels like home?','Where does life take you?','What makes it yours?'][s]}</h2><p class="card-intro">${['Just you, or a few of your favourite people.','A few practical details. You choose what matters.','Your routine is part of finding the right place.','The little things that make a place feel right.'][s]}</p>${s===0?`<details class="commercial-entry"><summary><span>${icon('building')}<span><strong>New commercial in need?</strong><small>Offices, Stores, Warehouses & more</small></span></span>${icon('plus')}</summary><div class="commercial-entry-body"><p>Space for your next venture. Select all that fit.</p><div class="choice-row">${COMMERCIAL_TYPES.map(([key,label])=>`<button class="choice ${state.commercialTypes.includes(key)?'selected':''}" aria-pressed="${state.commercialTypes.includes(key)}" data-action="commercial-type" data-type="${key}">${label}</button>`).join('')}</div><button class="text-button" data-action="commercial-search">Explore commercial spaces ${icon('arrow')}</button></div></details>`:''}<div class="step-fields">${profileFields(s)}</div><div class="form-footer"><span>${icon('lock')} Only share what you want.</span><button class="text-button" data-action="skip">${s===3?'Browse without adding more':'Skip this step'} ${icon('arrow')}</button></div><div class="step-actions">${s>0?`<button class="back-button" data-action="previous" aria-label="Previous step">${icon('back')}</button>`:''}<button class="primary-button" data-action="next">${s===3?'Let’s go':'Continue'} ${icon('arrow')}</button></div></div></div><div class="below-card"><span>YOUR LIFE IS THE STARTING POINT.</span><p>Feel free to fill out what you want.<br>We just want to remove friction.</p></div></section></div>`;
}
function profileFields(step){
 const p=state.profile;
 if(step===0&&state.intentMarket==='commercials')return `<div class="market-catalog-intro"><span>COMMERCIAL BRIEF</span><h3>What kind of space moves the business forward?</h3><p>This catalogue is separate from residential homes.</p></div><div class="commercial-catalog">${COMMERCIAL_TYPES.map(([key,label])=>`<button type="button" class="choice ${state.commercialTypes.includes(key)?'selected':''}" aria-pressed="${state.commercialTypes.includes(key)}" data-action="commercial-type" data-type="${key}">${icon(key==='office'?'building':'work')}<strong>${label}</strong></button>`).join('')}</div>`;
 if(step===1&&state.intentMarket==='sales')return `<div class="market-catalog-intro"><span>SALES BRIEF</span><h3>A purchase is a different decision.</h3><p>Purchase budget, property format and long-term priorities shape this catalogue.</p></div><div class="fields-grid">${requirementField('budget','Purchase budget',reqSelect('budget',[[150000,'Up to €150,000'],[250000,'Up to €250,000'],[400000,'Up to €400,000'],[600000,'Up to €600,000'],[1000000,'Up to €1,000,000'],[2000000,'Up to €2,000,000'],[5000000,'Up to €5,000,000']],'Keep purchase budget open'))}${requirementField('bedrooms','Bedrooms',rangeControl('bedrooms',p.requirements.bedrooms.value,{max:6,label:'Bedrooms',unit:'+'}))}${requirementField('bathrooms','Bathrooms',rangeControl('bathrooms',p.requirements.bathrooms.value,{max:5,label:'Bathrooms',unit:'+'}))}${requirementField('moveIn','Target purchase date',`<input id="req-moveIn" type="date" data-requirement="moveIn" value="${p.requirements.moveIn.value??''}">`)}</div><div class="requirement type-requirement"><div class="field-head"><label>Sales property catalogue <small class="multi-hint">Homes, blocks and developments</small></label>${importance('propertyType','sales property types')}</div><div data-profile-types>${typePickerMarkup('profile-type')}</div></div><div class="permission-preferences">${toggleRange('outdoor','Outdoor potential','Garden, terrace or other outdoor space.')}${toggleRange('luxuryProperty','Premium property','Prime finish, location or development.')}</div>`;
 if(step===1&&state.intentMarket==='stays')return `<div class="market-catalog-intro"><span>SHORTLET BRIEF</span><h3>Build the stay around dates and guests.</h3><p>Shortlet results keep nightly, weekly and full-stay prices separate.</p></div><div class="fields-grid">${requirementField('moveIn','Check-in date',`<input id="req-moveIn" type="date" data-requirement="moveIn" value="${p.requirements.moveIn.value??''}">`)}${requirementField('bedrooms','Bedrooms',rangeControl('bedrooms',p.requirements.bedrooms.value,{max:6,label:'Bedrooms',unit:'+'}))}${requirementField('bathrooms','Bathrooms',rangeControl('bathrooms',p.requirements.bathrooms.value,{max:5,label:'Bathrooms',unit:'+'}))}</div><div class="requirement type-requirement"><div class="field-head"><label>Stay catalogue <small class="multi-hint">Apartments, houses and serviced stays</small></label>${importance('propertyType','stay types')}</div><div data-profile-types>${typePickerMarkup('profile-type')}</div></div><p class="field-note">We never compare a nightly shortlet price with a monthly rent.</p>`;
 if(step===1&&state.intentMarket==='commercials')return `<div class="market-catalog-intro"><span>COMMERCIAL SPACE</span><h3>Practical requirements for the operation.</h3><p>Commercial results use their own inventory and never mix with homes.</p></div><div class="fields-grid">${requirementField('budget','Monthly space budget',rangeControl('budget',p.requirements.budget.value,{label:'Monthly space budget'}))}${requirementField('moveIn','Required from',`<input id="req-moveIn" type="date" data-requirement="moveIn" value="${p.requirements.moveIn.value??''}">`)}</div><div class="commercial-catalog">${COMMERCIAL_TYPES.map(([key,label])=>`<button type="button" class="choice ${state.commercialTypes.includes(key)?'selected':''}" aria-pressed="${state.commercialTypes.includes(key)}" data-action="commercial-type" data-type="${key}"><strong>${label}</strong></button>`).join('')}</div><p class="field-note">Office, retail, hospitality and industrial uses are queried as separate commercial types.</p>`;
 if(step===0)return `<div class="household-grid">${GROUPS.map(([key,label,desc,i])=>`<button class="household-option ${p.household===key?'selected':''}" data-profile="household" data-value="${key}" aria-pressed="${p.household===key}"><span class="household-icon">${icon(i)}</span><span class="selection-indicator">${p.household===key?icon('check'):''}</span><strong>${label}</strong><small>${desc}</small></button>`).join('')}</div><div class="adaptive-field">${p.household?`<label>${p.household==='sharing'?'How many people are sharing?':p.household==='family'?'How many people in your household?':'People in your household'}</label>${rangeControl('people',p.people,{max:8,kind:'simple',label:'People in your household',unit:' people'})}<p class="field-note">${p.household==='sharing'?'We will only show homes that explicitly permit sharing.':p.household==='couple'?'You can add separate work locations and schedules in the everyday step.':p.household==='family'?'Add school and work locations later. We keep space and outdoor needs separate.':'Your preferences stay open until you choose them.'}</p>`:`<div class="open-note">${icon('sparkle')} A home that fits your life starts with your people.</div>`}</div>`;
 if(step===1)return `<div class="fields-grid">${requirementField('budget','Monthly budget',rangeControl('budget',p.requirements.budget.value,{label:'Monthly budget'}))}${requirementField('bedrooms','Separate bedrooms',rangeControl('bedrooms',p.requirements.bedrooms.value,{max:6,label:'Separate bedrooms',unit:'+'}))}${requirementField('bathrooms','Bathrooms',rangeControl('bathrooms',p.requirements.bathrooms.value,{max:5,label:'Bathrooms',unit:'+'}))}${requirementField('duration','Rental duration',rangeControl('duration',p.requirements.duration.value,{max:36,step:3,label:'Rental duration',unit:' months'}))}${requirementField('moveIn','Move-in date',`<input id="req-moveIn" type="date" data-requirement="moveIn" value="${p.requirements.moveIn.value??''}">`)}</div><div class="requirement type-requirement"><div class="field-head"><label>Property types <small class="multi-hint">Combine groups or choose individual types</small></label>${importance('propertyType','property types')}</div><div data-profile-types>${typePickerMarkup('profile-type')}</div></div><div class="permission-preferences">${toggleRange('pets','Pet-friendly','Preferred, with room to ask the owner. Unconfirmed permission stays visible.')}${toggleRange('subletting','Subletting allowed','Only properties with explicit permission. Never assumed.')}</div><details class="more-fields"><summary>Outdoor space & finishing ${icon('plus')}</summary>${[['balcony','Balcony'],['outdoor','Outdoor space'],['luxuryProperty','Premium property']].map(([key,label])=>`<div class="form-section"><div class="field-head"><span>${label}</span>${importance(key,label)}</div>${toggleRange(key,label,'Keep this open, or add it to your preferences.')}</div>`).join('')}</details><p class="field-note">“Required” is a must-have. Subletting always needs confirmed permission.</p>`;
 if(step===2)return `<div class="form-section"><label>How do you usually get around?</label>${chips('transport',[['car','Car','car'],['bus','Bus','bus'],['bolt','Bolt','bolt'],['walk','Walk','walk'],['mixed','Mixed','map']])}</div><div class="form-section"><label>Where do you work?</label>${chips('homeOffice',[['onsite','On-site'],['hybrid','Hybrid'],['remote','From home']])}</div><div class="anchor-list">${p.anchors.map((a,i)=>`<div class="anchor-form"><div class="anchor-heading"><strong>${icon(a.type==='school'?'school':'work')}${esc(a.person)} · ${a.type==='school'?'School':'Work'}</strong><button class="icon-button" data-action="remove-anchor" data-index="${i}" aria-label="Remove ${esc(a.person)} ${a.type} location">${icon('close')}</button></div><label for="anchor-${i}">Area or address <span class="muted">(optional)</span></label><input id="anchor-${i}" maxlength="120" data-anchor="${i}" data-field="location" placeholder="e.g. Sliema" value="${esc(a.location)}"><div class="fields-grid"><div><label>Days per week</label>${rangeControl('days',a.days,{max:7,kind:'anchor',anchor:i,label:`Days per week for ${a.person}`,unit:' days'})}</div><label>Usual arrival<input aria-label="Arrival time for ${esc(a.person)}" type="time" data-anchor="${i}" data-field="time" value="${esc(a.time)}"></label></div></div>`).join('')}</div><div class="add-anchor-actions"><button class="outline-button" data-action="add-anchor" data-type="work">${icon('plus')} ${p.household==='couple'&&p.anchors.some(a=>a.type==='work')?'Add partner’s work':'Add work location'}</button>${p.household==='family'?`<button class="outline-button" data-action="add-anchor" data-type="school">${icon('plus')} Add school</button>`:''}</div><p class="field-note">Personal locations stay in this browser session. Travel times need route data; distance alone is not a commute.</p>`;
 return `<div class="form-section"><div class="field-head"><label>Preferred areas <small class="multi-hint">Choose as many as you like</small></label>${importance('locations','preferred areas')}</div><div class="location-choices"></div></div><div class="priorities-list">${PRIORITIES.map(([key,label,i])=>`<div class="priority-row"><span>${icon(i)}${label}</span><label class="priority-slider"><span>${IMPORTANCE.find(x=>x[0]===p.priorities[key])?.[1]||'Keep open'}</span><input type="range" min="0" max="4" step="1" value="${['',...preferenceLevels].indexOf(p.priorities[key]||'')}" aria-label="Importance of ${label}" data-priority-range="${key}"></label></div>`).join('')}</div><div class="form-section"><label>How often do you enjoy going out?</label>${chips('nightlife',[['often','Often'],['weekly','Weekly'],['rarely','Rarely']])}</div><label class="checkbox-label"><input type="checkbox" id="allow-outside" ${p.allowOutside?'checked':''}> I’m open to inspiration outside my brief.</label><p class="field-note">These options stay separate. Required criteria still apply.</p>`;
}
function modal(title,body,cls=''){const m=$('#modal');m.className=cls;m.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}`;if(!m.open)m.showModal();}
function setIntentMarket(market){if(!['longlets','sales','stays','commercials'].includes(market))return;state.intentMarket=market;document.body.dataset.intentMarket=market;try{sessionStorage.setItem('nexus-link-intent-market',market);}catch{}if(market==='commercials')state.profile.household=null;}
function chooseMarketAtStart(){if(state.intentMarket||!initialProfile)return Promise.resolve();return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='market-intent';dialog.setAttribute('aria-labelledby','market-intent-title');dialog.innerHTML=`<div class="market-intent-mark">✦</div><span>START WITH WHAT YOU NEED</span><h2 id="market-intent-title">What are you looking for?</h2><p>Choose your path first. The questions, catalogue and results adapt to it. You can switch at any time.</p><div class="market-intent-grid">${[['longlets','Rent','A home for months or years','home'],['sales','Buy','Homes and investments for sale','building'],['stays','Shortlets','A stay with dates and guests','bed'],['commercials','Commercial','Office, retail, hospitality and more','work']].map(([market,label,copy,symbol])=>`<button type="button" data-intent-market="${market}">${icon(symbol)}<strong>${label}</strong><small>${copy}</small><i>↗</i></button>`).join('')}</div>`;document.body.append(dialog);dialog.showModal();dialog.addEventListener('cancel',event=>event.preventDefault());dialog.onclick=event=>{const button=event.target.closest('[data-intent-market]');if(!button)return;setIntentMarket(button.dataset.intentMarket);dialog.close();dialog.remove();renderProfile();resolve();};});}
function updateHeader(){const page=(location.hash.slice(1).split('/')[0]||'profile');document.querySelectorAll('[data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===page);if(el.dataset.nav===page)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});document.querySelectorAll('[data-saved-count]').forEach(el=>el.textContent=state.favorites.size);}
function loading(label='Finding your next chapter…'){document.body.dataset.page='results';$('#content').innerHTML=`<section class="loading-state"><span class="loading-star">✦</span><h1>${label}</h1><p>Connecting your preferences to the available homes.</p></section>`;}
async function renderRoute(){updateHeader();const route=location.hash.slice(1)||'profile';if(route==='profile'||route==='content'){state.request++;renderProfile();}else await renderDestination(route);attachMapDock();}
async function getCandidates(){const response=await searchCache.get();state.results=response;state.displayProperties=response.properties;mapExperience.setProperties(response.properties);placesControl?.render();if(adapter.mode==='argus'&&response.generatedAt){let label=document.querySelector('.inventory-freshness');if(!label&&document.querySelector('.intro-foot')){label=document.createElement('p');label.className='inventory-freshness';document.querySelector('.intro-foot').before(label);}if(label)label.textContent='2906 collection · '+(response.mode==='live'?'Live · ':'Snapshot · ')+new Date(response.generatedAt).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})+' · '+response.properties.filter(p=>!p.designOnly).length+' public offers';}return response;}
async function getResults(){const response=await getCandidates();return {...response,properties:matchSearch(response.properties,mapExperience.getFilters(),state.profile,DEVELOPMENTS)};}
async function renderDestination(route){
 const request=++state.request;loading();
 try{
  if(route==='homes'||route==='saved'||route==='compare'){
   const response=await getResults();if(request!==state.request)return;
   if(route==='compare'){const selected=await Promise.all([...state.compare].map(id=>adapter.getProperty(id).then(p=>({...p,match:response.properties.find(x=>x.id===id)?.match})).catch(()=>null)));if(request!==state.request)return;renderComparison(selected.filter(Boolean));return;}
   let properties=response.properties;
   if(route==='saved'){properties=await Promise.all([...state.favorites].map(id=>adapter.getProperty(id).then(p=>({...p,match:response.properties.find(r=>r.id===id)?.match})).catch(()=>null)));if(request!==state.request)return;properties=properties.filter(Boolean);}
   renderResults(properties,route==='saved');
  }else if(route.startsWith('property/')){
   const id=decodeURIComponent(route.slice(9));const property=await adapter.getProperty(id);if(request!==state.request)return;const results=await getResults();if(request!==state.request)return;
   renderProperty({...property,...results.properties.find(p=>p.id===id)});
  }else if(route==='developments'){renderDevelopments();}
  else if(route.startsWith('development/')){const d=await adapter.getDevelopment(decodeURIComponent(route.slice(12)));if(request!==state.request)return;renderDevelopment(d);}
  else if((route==='map'||route==='results')){const response=await getResults();if(request!==state.request)return;renderResults(response.properties);attachMapDock();await openMap();}
  else {renderError('This page could not be found.');}
 }catch(error){if(request===state.request)renderError(error.message);}
}
async function openMap(target){try{const response=await getCandidates();mapExperience.setProperties(response.properties);await mapExperience.expand(target);}catch(error){toast(error.message);}}
async function finishProfile(){persist();const button=document.querySelector(`[data-scroll-step="${state.step}"] [data-action="next"]`);if(button){button.disabled=true;button.textContent='Finding your possibilities…';}try{const response=await getCandidates();mapExperience.setProperties(response.properties);await mapExperience.browseMarket(state.intentMarket||'longlets');}catch(error){toast(error.message);}finally{if(button){button.disabled=false;button.innerHTML='Let’s go '+icon('arrow');}}}
async function revealPropertyFromMap(id){
 try{const [property,response]=await Promise.all([adapter.getProperty(id),getResults()]);
 const host=mapExperience.openPropertyDetail();renderProperty({...property,...response.properties.find(p=>p.id===id)},host);host.querySelector('h1')?.focus({preventScroll:true});
 }catch(error){toast(error.message);}
}

function profileSummary(){
 const p=state.profile;const household=GROUPS.find(g=>g[0]===p.household)?.[1];
 const parts=[household,...activeRequirements(p).map(([key,r])=>key==='budget'?`${money(r.value)} max rent`:key==='propertyType'?asTypes(r.value).map(typeLabel).join(', '):key==='locations'?r.value.join(', '):key==='bedrooms'?`${r.value}+ bedrooms`:key==='bathrooms'?`${r.value}+ bathrooms`:key==='duration'?`${r.value} months`:key==='moveIn'?`From ${dateLabel(r.value)}`:r.value===true?key.replace(/([A-Z])/g,' $1'):String(r.value))].filter(Boolean);
 return parts.length?parts.map(part=>`<span class="brief-chip">${esc(part)}</span>`).join(''):'<p class="muted">An open brief. Add what matters to you.</p>';
}
function resultBadge(p){return p.searchMatch?`<span class="fit-badge ${p.searchMatch.kind}">${icon('sparkle')}${p.searchMatch.kind==='direct'?'Direct match':'Alternative match'}</span>`:p.match?.fit?`<span class="fit-badge ${p.match.category}">${icon('sparkle')}${categories[p.match.category]||'Match'}</span>`:'<span class="fit-badge">OPEN BRIEF</span>';}
function facts(p){const values=[];if(Number.isFinite(p.bedrooms))values.push(`${icon('bed')}${p.bedrooms} ${p.bedrooms===1?'bed':'beds'}${p.study?' + study':''}`);if(Number.isFinite(p.bathrooms))values.push(`${icon('bath')}${p.bathrooms} ${p.bathrooms===1?'bath':'baths'}`);if(Number.isFinite(p.size))values.push(`${icon('area')}${p.size} m²`);return `<div class="permission-badges">${p.pets===true?'<span>Pet-friendly</span>':state.profile.requirements.pets.value===true?`<span class="needs-confirmation">${p.pets===false?'Pets not currently permitted':'Pet permission · ask the owner'}</span>`:''}${p.subletting===true?'<span>Subletting permitted</span>':''}</div>${values.length?`<div class="property-facts">${values.map(value=>`<span>${value}</span>`).join('')}</div>`:'<div class="property-facts property-facts-pending"><span>Bedrooms, bathrooms and size to confirm</span></div>'}`;}
function gallery(p,large=false){return `<div class="gallery ${large?'large-gallery':''}" data-gallery="${esc(p.id)}"><div class="photo-track" aria-label="Property photos" tabindex="0">${p.images.map((key,i)=>`<div class="photo-slide">${imageTag(key,`${p.demo?'Illustrative interior':'Property photograph'} ${i+1} of ${p.images.length} for ${p.area}`,'',!large||i>0)}</div>`).join('')}</div><span class="photo-disclosure">${p.demo?'ILLUSTRATIVE IMAGES':'PROPERTY PHOTOS'}</span><button class="favorite-button ${state.favorites.has(p.id)?'saved':''}" data-action="favorite" data-id="${esc(p.id)}" aria-label="${state.favorites.has(p.id)?'Unsave':'Save'} ${esc(p.title)}" aria-pressed="${state.favorites.has(p.id)}">${icon('heart')}</button><button class="super-favorite-button" data-action="super-favorite" data-id="${esc(p.id)}" aria-label="${state.superFavorites.has(p.id)?'Remove super favorite':'Super favorite'} ${esc(p.title)}" aria-pressed="${state.superFavorites.has(p.id)}">✦</button><button class="property-activity" data-action="activity" data-id="${esc(p.id)}" aria-label="Activities around ${esc(p.title)}">${activityIcon}<span>Activities</span></button><div class="gallery-controls"><button data-action="photo-prev" aria-label="Previous photo" class="gallery-arrow">${icon('back')}</button><span class="photo-count">1 / ${p.images.length}</span><button data-action="photo-next" aria-label="Next photo" class="gallery-arrow">${icon('arrow')}</button></div><div class="gallery-caption">${icon('pin')} ${esc(p.area)}<span>${p.developmentId?esc(DEVELOPMENTS.find(d=>d.id===p.developmentId)?.name||''):''}</span></div></div>`;}
function card(p){return `<article class="property-card" id="card-${esc(p.id)}">${gallery(p)}<div class="property-body"><div class="property-topline">${resultBadge(p)}<span class="availability">${p.designOnly?'DESIGN EXAMPLE':p.status==='available'?`${p.availableFrom?'From '+dateLabel(p.availableFrom):'Date to confirm'}`:'No longer available'}</span></div><div class="property-title-row"><div><a href="#property/${encodeURIComponent(p.id)}"><h2>${esc(p.title)}</h2></a><p>${esc(p.area)} · ${esc(p.propertyType)} · ${p.market==='sales'?'Sale':p.market==='commercials'?'Commercial':p.market==='stays'?'Shortlets & stays':p.rentalModes?.includes('WINTER_LET')&&!p.rentalModes.includes('LONG_LET')?'Winterlet':'Longlet'}</p></div><div class="rent">${money(p.rent)}<small>${p.market==='sales'?'asking price':'/ '+(p.rentPeriod||'month')}</small></div></div>${facts(p)}<p class="property-location-note">Approximate map location · exact address kept private.</p><div class="fit-explanation">${icon('sparkle')}<p>${esc(p.designOnly?p.description:p.match?.reason||p.editorial||p.description)}</p></div><div class="property-bottom"><span class="fit-detail">${p.match?.fit?esc(p.match.fit):'Add preferences to see your fit'}${p.match?.unknown?` · ${p.match.unknown} unverified`:''}</span><div><button class="text-button compare-button ${state.compare.has(p.id)?'selected':''}" data-action="compare" data-id="${esc(p.id)}" aria-pressed="${state.compare.has(p.id)}">${icon('compare')}${state.compare.has(p.id)?'Comparing':'Compare'}</button><a class="property-open" href="#property/${encodeURIComponent(p.id)}" aria-label="View ${esc(p.title)}">${icon('arrow')}</a></div></div></div></article>`;}
function renderResults(properties,saved=false){
 document.body.dataset.page='results';
 const visible=properties.filter(p=>saved||availableInWeek(p,state.week)).filter(p=>saved||state.category==='all'||p.match?.category===state.category);
 const counts=Object.fromEntries(Object.keys(categories).map(key=>[key,properties.filter(p=>availableInWeek(p,state.week)&&p.match?.category===key).length]));
 const required=activeRequirements(state.profile).filter(([,r])=>r.importance==='required').length;
 $('#content').innerHTML=`<div class="results-page"><div class="results-heading"><div><div class="eyebrow">${icon(saved?'heart':'sparkle')} ${saved?'YOUR PERSONAL SELECTION':'YOUR NEXT CHAPTER'}</div><h1>${saved?'Keep the possibilities.':'Find your kind of everyday.'}</h1><p>${saved?(adapter.mode==='demo'?'Your favourite demo homes, saved on this device.':'Your saved homes.'):'Your home, your surroundings, your everyday. See how it all fits.'}</p></div><div class="heading-actions">${demoNote()}<a class="outline-button" href="#profile">${icon('sliders')} Edit your profile</a></div></div>
 <div class="results-toolbar"><div class="week-tabs" aria-label="Availability week">${['this','next','later'].map((w,i)=>`<button data-action="week" data-week="${w}" class="${state.week===w?'active':''}" aria-pressed="${state.week===w}">${['This week','Next week','Later'][i]}</button>`).join('')}</div><span class="result-count">${visible.length} ${adapter.mode==='demo'?'demo ':''}homes ${saved?'saved':'to explore'}</span><a class="saved-in-results" href="#saved">${icon('heart')} Saved <b>${state.favorites.size}</b></a><div class="view-toggle"><button data-action="view-list" class="${state.view==='list'?'active':''}" aria-pressed="${state.view==='list'}">${icon('home')} Homes</button><button data-action="view-map" class="${state.view==='map'?'active':''}" aria-pressed="${state.view==='map'}">${icon('map')} Map</button></div></div>
 ${!saved?`<div class="category-tabs" aria-label="Result groups"><button class="${state.category==='all'?'active':''}" data-action="category" data-category="all" aria-pressed="${state.category==='all'}">All possibilities <span>${properties.filter(p=>availableInWeek(p,state.week)).length}</span></button>${Object.entries(categories).filter(([key])=>key!=='outside'||state.profile.allowOutside).map(([key,label])=>`<button class="${state.category===key?'active':''}" data-action="category" data-category="${key}" aria-pressed="${state.category===key}">${label}<span>${counts[key]}</span></button>`).join('')}</div>`:''}

 <div class="results-layout"><div class="property-feed">${visible.length?visible.map(card).join(''):emptyState(saved?'Your shortlist starts here.':'No homes in this view.',saved?'Tap a heart on any home to keep it here.':'Try another week or result group, or adjust your profile. Your required criteria have not been relaxed.',saved?'Explore homes':'Edit your profile',saved?'#results':'#profile')}</div><aside class="results-sidebar"><section class="brief-panel"><div class="panel-title">${icon('sliders')} YOUR LIVING PROFILE <a href="#profile" aria-label="Edit living profile">${icon('arrow')}</a></div><div class="brief-chips">${profileSummary()}</div><div class="brief-divider"></div><p>${required?`${required} required ${required===1?'criterion':'criteria'} protected.`:'You choose what is essential.'}</p><small>Required criteria are never exchanged for a lifestyle match.</small>${state.results?.excluded?.length?`<button class="text-button" data-action="excluded">${state.results.excluded.length} homes outside your requirements ${icon('info')}</button>`:''}</section><section class="map-teaser"><div class="map-teaser-top"><span>ANOTHER PERSPECTIVE</span>${icon('map')}</div><h3>See the place.<br>Feel the possibilities.</h3><p>Explore the existing Nexus 3D map when you want more context.</p><button class="light-button" data-action="open-map">Explore the map ${icon('arrow')}</button></section><section class="life-cost-panel"><div class="panel-title">${icon('coin')} BEYOND THE RENT</div><h3>A different kind<br>of life cost.</h3><p>Rent and recurring mobility, side by side. Your time stays separate.</p><div class="cost-example"><span>€1,700 rent + €360 mobility</span><b>€2,060</b></div><div class="cost-example highlight"><span>€1,900 rent + €40 mobility</span><b>€1,940</b></div><p class="savings">${money(120)} less per month, despite higher rent.</p><small>Illustrative examples. Utilities and other living costs are not included.</small><button class="text-button" data-action="example-compare">Explore the comparison ${icon('arrow')}</button></section></aside></div><p class="results-footnote">${adapter.mode==='demo'?'Demo prices, status and availability are illustrative. ':''}Availability is not a reservation. Homes remain visible in a later week only while their status and rental terms allow it.</p></div>${compareTray()}`;
 bindGalleries();
}
function emptyState(title,copy,label,href){return `<div class="empty-state">${icon('sparkle')}<h2>${title}</h2><p>${copy}</p><a class="primary-button" href="${href}">${label}${icon('arrow')}</a></div>`;}
