function renderError(message){$('#content').innerHTML=`<section class="simple-page">${emptyState('Let’s reconnect.',esc(message),'Return to your profile','#profile')}</section>`;}
function fitRows(p){return p.match?.checks?.length?p.match.checks.map(c=>`<div class="fit-row"><span class="fit-status ${c.met===true?'met':c.met===false?'miss':'unknown'}">${icon(c.met===true?'check':c.met===false?'minus':'info')}</span><span><strong>${esc(c.label)}</strong><small>${IMPORTANCE.find(x=>x[0]===c.importance)?.[1]||''}</small></span><b>${c.met===true?'Meets':c.met===false?'Trade-off':'Unverified'}</b></div>`).join(''):'<p class="muted">Your brief is open. Add preferences to see what matches and what needs a closer look.</p>';}
function renderProperty(p,target=$('#content')){
 if(target===$('#content'))document.body.dataset.page='property';state.currentProperty=p;if(!state.displayProperties?.some(item=>item.id===p.id))state.displayProperties=[...(state.displayProperties||[]),p];
 target.innerHTML=`<div class="detail-page"><div class="detail-breadcrumb"><a href="#map">${icon('back')} Back to your possibilities</a><span>${demoNote()}</span><button class="text-button" data-action="share-property" data-id="${esc(p.id)}">${icon('share')} Share home</button></div>${gallery(p,true)}<div class="detail-grid"><section><div class="property-topline">${resultBadge(p)}<span class="availability">${p.designOnly?'DESIGN EXAMPLE':p.status==='available'?`${p.availableFrom?'Available from '+dateLabel(p.availableFrom):'Available in snapshot · date to confirm'}`:'No longer available'}</span></div><h1 tabindex="-1">${esc(p.title)}</h1><p class="detail-location">${icon('pin')}${esc(p.area)}${p.developmentId?` · <a href="#development/${encodeURIComponent(p.developmentId)}">${esc(DEVELOPMENTS.find(d=>d.id===p.developmentId)?.name||'View development')} ${icon('arrow')}</a>`:''}</p>${facts(p)}<p class="property-location-note">Approximate map location · exact address kept private.</p><p class="description">${esc(p.description)}</p><div class="amenities">${p.features.map(f=>`<span>${icon('check')}${esc(f)}</span>`).join('')}</div>${pillarMarkup(p)}<section class="detail-section"><h2>A fit you can understand.</h2><p>Your preferences, the trade-offs and the details still to verify.</p>${fitRows(p)}<p class="field-note">${p.demo?'Based on fictional demo records. ':''}Unverified details are never counted as a confirmed match. A study or sofa does not replace a separate bedroom.</p></section><section class="detail-section"><h2>Life Cost, made clearer.</h2><div class="cost-grid"><div><span>${p.market==='sales'?'Asking price':'Monthly rent'}</span><strong>${money(p.rent)}</strong></div><div><span>Recurring mobility${p.mobility?' · illustrative':''}</span><strong>${p.mobility?money(p.mobility.monthly):'Not available'}</strong></div><div class="total-cost"><span>${p.market==='sales'?'Recurring mobility':'Rent + mobility'}</span><strong>${p.mobility?money(p.rent+p.mobility.monthly):'Awaiting mobility data'}</strong></div></div><p class="field-note">${p.mobility?esc(p.mobility.assumption):'Your routes, travel frequency and transport data are needed for an estimate.'} Utilities, internet and other expenses are not included.</p><div class="time-separate">${icon('clock')}<div><strong>Your time is a separate measure.</strong><p>Travel time is not available until route data is connected. We do not turn your time into a euro amount.</p></div></div></section></section><aside><div class="viewing-panel"><span class="eyebrow">YOUR NEXT CHAPTER</span><div class="detail-price">${money(p.rent)}<span>${p.market==='sales'?'asking price':'/ '+(p.rentPeriod||'month')}</span></div><p>${p.market==='sales'?'Purchase opportunity':p.minMonths&&p.maxMonths?`${p.minMonths}–${p.maxMonths} month rental term`:'Term to confirm'}</p><div class="brief-divider"></div><span class="status-line">${p.designOnly?'DESIGN EXAMPLE':p.status==='available'?`${p.availableFrom?'From '+dateLabel(p.availableFrom):'Date to confirm'}`:'No longer available'}</span><button class="primary-button" data-action="viewing" data-id="${esc(p.id)}" ${p.status!=='available'?'disabled':''}>View viewing options ${icon('arrow')}</button><button class="outline-button" data-action="favorite" data-id="${esc(p.id)}" aria-pressed="${state.favorites.has(p.id)}">${icon('heart')}${state.favorites.has(p.id)?'Saved to your homes':'Save this home'}</button><button class="text-button" data-action="compare" data-id="${esc(p.id)}">${icon('compare')}${state.compare.has(p.id)?'Remove from comparison':'Add to comparison'}</button><small>${p.demo?'Demo home. No viewing requests can be sent yet.':'Viewings are confirmed only after the booking service accepts your selected slot.'}</small></div><button class="property-map-button" data-action="property-map" data-id="${esc(p.id)}">${icon('map')}Open location & surroundings${icon('arrow')}</button></aside></div></div>${compareTray()}`;
 bindGalleries();
}
function renderComparison(properties){
 document.body.dataset.page='compare';const selected=properties.filter(p=>state.compare.has(p.id));
 if(selected.length<2){$('#content').innerHTML=`<section class="simple-page">${emptyState('Some things are better side by side.','Choose at least two homes to compare rent, space and the everyday trade-offs.','Explore homes','#results')}</section>`;return;}
 const rows=[['Monthly rent',p=>money(p.rent)],['Recurring mobility',p=>p.mobility?`${money(p.mobility.monthly)} · illustrative`:'Not available'],['Rent + mobility',p=>p.mobility?money(p.rent+p.mobility.monthly):'Not calculated'],['Commute time',()=> 'Route data needed'],['Separate bedrooms',p=>`${p.bedrooms}${p.study?' + study (not a bedroom)':''}`],['Bathrooms',p=>p.bathrooms],['Floor area',p=>`${p.size??'—'} m²`],['Balcony',p=>p.balcony?'Yes':'No'],['Pets',p=>p.pets?'Allowed':'Not permitted'],['Sharing',p=>p.sharing?'Permitted':'Not permitted'],['Rental term',p=>`${p.minMonths}–${p.maxMonths} months`],['Available from',p=>dateLabel(p.availableFrom)],['What to consider',p=>p.match?.reason||p.editorial]];
 $('#content').innerHTML=`<section class="comparison-page"><a class="text-button" href="#map">${icon('back')} Back to homes</a><div class="results-heading"><div><div class="eyebrow">THE WHOLE PICTURE</div><h1>Different places. Different lives.</h1><p>Compare what you gain, what you give up and what is still unknown.</p></div>${demoNote()}</div><div class="comparison-scroll"><table class="comparison-table"><thead><tr><th scope="col">Your everyday,<br>side by side.</th>${selected.map(p=>`<th scope="col">${imageTag(p.images[0],`${p.demo?'Illustrative ':''}interior in ${p.area}`)}<a href="#property/${encodeURIComponent(p.id)}">${esc(p.area)} ${icon('arrow')}</a><small>${esc(p.title)}</small></th>`).join('')}</tr></thead><tbody>${rows.map(([label,get])=>`<tr class="${label==='Rent + mobility'?'total-row':''}"><th scope="row">${label}</th>${selected.map(p=>`<td>${esc(get(p))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="results-footnote">${adapter.mode==='demo'?'Illustrative comparison, not live offers. ':''}Rent + mobility includes only those two costs. No value is assigned to time. Unavailable data is not treated as zero.</p></section>`;
}
function developmentTile(d){return `<a class="development-tile" href="#development/${encodeURIComponent(d.id)}"><div class="development-image">${d.image?`<img src="${esc(d.image)}" alt="${esc(d.name)} development" loading="lazy">`:`<div class="development-symbol">${icon('building')}<span>NEXUS LANDMARK COLLECTION</span></div>`}<span class="development-gold">${icon('building')}</span></div><div><span>${esc(d.area)}</span><h2>${esc(d.name)}${icon('arrow')}</h2></div></a>`;}
function renderDevelopments(){document.body.dataset.page='developments';$('#content').innerHTML=`<section class="developments-page"><div class="results-heading"><div><div class="eyebrow">THE LANDMARK COLLECTION</div><h1>Extraordinary places.<br>Your next possibility.</h1><p>One development, all its homes. Explore Malta’s residential landmarks.</p></div><button class="outline-button" data-action="open-map">${icon('map')} Explore on the map</button></div><div class="developments-grid">${DEVELOPMENTS.map(developmentTile).join('')}</div></section>`;}
function renderDevelopment(d){
 document.body.dataset.page='development';state.currentDevelopment=d;
 const now=new Date().toLocaleDateString('en-CA');const current=d.properties.filter(p=>p.status==='available'&&(!p.availableFrom||p.availableFrom<=now)),upcoming=d.properties.filter(p=>p.status==='available'&&p.availableFrom>now);
 $('#content').innerHTML=`<section class="development-page"><a href="#developments" class="text-button">${icon('back')} The landmark collection</a><div class="development-hero">${d.image?`<img src="${esc(d.image)}" alt="${esc(d.name)}">`:`<div class="development-symbol">${icon('building')}</div>`}<div><span class="eyebrow">${esc(d.area)} · NEXUS LANDMARK</span><h1>${esc(d.name)}</h1><p>${esc(d.description)}</p><button class="light-button" data-action="development-map" data-id="${esc(d.id)}">Explore on the map ${icon('arrow')}</button><button class="area-activity" data-action="development-activity" data-id="${esc(d.id)}">${activityIcon} Activities around this place</button></div></div><div class="development-inventory"><h2>Current possibilities <span>${current.length}</span></h2>${current.length?current.map(card).join(''):emptyState('No current homes connected.','Live inventory will appear here when the 2906 connection is ready.','Explore other developments','#developments')}<h2>Coming up <span>${upcoming.length}</span></h2>${upcoming.length?upcoming.map(card).join(''):'<p class="muted">No upcoming homes in this preview.</p>'}<p class="field-note">${demoNote()} Each property belongs to one development record, even when several building markers represent it.</p></div></section>`;bindGalleries();
}
document.addEventListener('click',async event=>{
 const target=event.target.closest('button,a');if(!target)return;
 if(target.dataset.profile){const key=target.dataset.profile,value=target.dataset.value;state.profile[key]=state.profile[key]===value?null:value;persist();renderProfile();return;}
 const action=target.dataset.action;if(!action)return;
 if(action==='step')scrollProfileTo(Number(target.dataset.step));
 if(action==='previous')scrollProfileTo(Number(target.closest('[data-scroll-step]').dataset.scrollStep)-1);
 if(action==='next'||action==='skip'){state.step=Number(target.closest('[data-scroll-step]').dataset.scrollStep);if(action==='next'&&!validateStep())return;if(state.step<3)scrollProfileTo(state.step+1);else await finishProfile();}
 if(action==='add-anchor'){if(state.profile.anchors.length>=6){toast('Up to six daily locations can be added.');return;}const type=target.dataset.type,workCount=state.profile.anchors.filter(a=>a.type==='work').length;state.profile.anchors.push({type,person:type==='school'?'School':workCount===0?'You':state.profile.household==='couple'?'Partner':`Person ${workCount+1}`,location:'',days:null,time:'',coordinates:null});persist();renderProfile();}
 if(action==='remove-anchor'){state.profile.anchors.splice(Number(target.dataset.index),1);persist();renderProfile();}
 if(action==='location'){const arr=state.profile.requirements.locations.value;const name=target.dataset.location;state.profile.requirements.locations.value=arr.includes(name)?arr.filter(n=>n!==name):[...arr,name];persist();renderProfile();}
 if(action==='close-modal')$('#modal').close();
 if(action==='about')modal('A preview of a more connected life.',`<p>NEXUS LINK is the property decision interface. 2906 / ARGUS will supply live inventory, matching results and operational actions.</p><p>This preview uses fictional homes, illustrative AI-generated interiors and demo rules. Prices, availability and Life Cost examples are not current offers. No viewing can be booked here yet.</p><p>Saved demo homes stay on this device. Your living profile and private locations stay in this browser session and are not included in shared property links.</p>`);
 await handleProductAction(action,target);
});
function validateStep(){const fields=[...document.querySelectorAll(`[data-scroll-step="${state.step}"] .step-fields input`)];for(const field of fields)if(!field.checkValidity()){field.reportValidity();return false;}return true;}
document.addEventListener('input',event=>{
 const el=event.target;
 if(el.dataset.range){const key=el.dataset.range,value=(key==='budget'?budgetFromPosition(el.value):Number(el.value))||null;if(key==='budget')state.profile.requirements.budget.openEnded=Number(el.value)===100;
  if(el.dataset.rangeKind==='simple')state.profile[key]=value;
  else if(el.dataset.rangeKind==='anchor')state.profile.anchors[Number(el.dataset.rangeAnchor)][key]=value;
  else state.profile.requirements[key].value=value;
  const label=value===null?'Keep open':key==='budget'?budgetLabel(value,state.profile.requirements.budget.openEnded):`${value}${el.dataset.rangeUnit||''}`;
  el.closest('.range-control').querySelector('output').textContent=label;el.setAttribute('aria-valuetext',label);el.style.setProperty('--range-fill',`${Number(el.value)/Number(el.max)*100}%`);
  persist();
 }
 if(el.dataset.toggleRange){const key=el.dataset.toggleRange,value=el.value==='1'?true:null;state.profile.requirements[key].value=value;if(key==='subletting')state.profile.requirements[key].importance='required';el.nextElementSibling.textContent=value?'Yes':'Open';el.setAttribute('aria-valuetext',value?'Yes':'Keep open');persist();}
 if(el.dataset.importance){const value=preferenceLevels[Number(el.value)],label=IMPORTANCE.find(x=>x[0]===value)[1];state.profile.requirements[el.dataset.importance].importance=value;el.previousElementSibling.textContent=label;el.setAttribute('aria-valuetext',label);persist();}
 if(el.dataset.priorityRange){const value=['',...preferenceLevels][Number(el.value)],label=IMPORTANCE.find(x=>x[0]===value)?.[1]||'Keep open';if(value)state.profile.priorities[el.dataset.priorityRange]=value;else delete state.profile.priorities[el.dataset.priorityRange];el.previousElementSibling.textContent=label;el.setAttribute('aria-valuetext',label);persist();}
});
document.addEventListener('change',event=>{const el=event.target;
 if(el.dataset.requirement){const key=el.dataset.requirement;let v=el.value||null;if(['budget','bedrooms','bathrooms','duration'].includes(key))v=v===null?null:Number(v);if(['pets','balcony','outdoor','luxuryProperty'].includes(key))v=v==='true'?true:null;state.profile.requirements[key].value=v;persist();}
 if(el.dataset.importance&&el.type!=='range'){state.profile.requirements[el.dataset.importance].importance=el.value;persist();}
 if(el.dataset.simple){state.profile[el.dataset.simple]=el.value?Number(el.value):null;persist();}
 if(el.dataset.anchor!==undefined){const a=state.profile.anchors[Number(el.dataset.anchor)];a[el.dataset.field]=el.dataset.field==='days'?(el.value?Number(el.value):null):el.value;persist();}
 if(el.dataset.priority){el.value?state.profile.priorities[el.dataset.priority]=el.value:delete state.profile.priorities[el.dataset.priority];persist();}
 if(el.id==='allow-outside'){state.profile.allowOutside=el.checked;persist();}
});
async function handleProductAction(action,target){
 const id=target.dataset.id;
 if(action==='restore-search'&&lastSearch){state.profile=restoreProfile(lastSearch.profile);persist();mapExperience.restoreSearch(lastSearch.filters);renderProfile();const response=await getCandidates();mapExperience.setProperties(response.properties);toast('Last search restored. Your filters are active again.');}
 if(action==='commercial-type'){const type=target.dataset.type;state.commercialTypes=state.commercialTypes.includes(type)?state.commercialTypes.filter(t=>t!==type):[...state.commercialTypes,type];const selected=state.commercialTypes.includes(type);target.classList.toggle('selected',selected);target.setAttribute('aria-pressed',String(selected));}
 if(action==='commercial-search'){try{await mapExperience.browseCommercial(state.commercialTypes);}catch(error){toast(error.message);}}
 if(action==='map-market'){try{setIntentMarket(target.dataset.market);document.querySelectorAll('[data-action="map-market"]').forEach(button=>{button.classList.toggle('active',button.dataset.market===state.intentMarket);button.setAttribute('aria-pressed',String(button.dataset.market===state.intentMarket));});await mapExperience.browseMarket(target.dataset.market);}catch(error){toast(error.message);}}
 if(action==='week'){state.week=target.dataset.week;await renderRoute();}
 if(action==='category'){state.category=target.dataset.category;await renderRoute();}
 if(action==='view-list'){state.view='list';await renderRoute();}
 if(action==='view-map'||action==='reveal-map')await openMap();
 if(action==='activity'){const p=await adapter.getProperty(id);await mapExperience.openActivity({id:p.id,kind:'property',name:p.title,subtitle:money(p.rent)+' / '+(p.rentPeriod||'month')+' · '+p.area,image:photoUrl(p.images[0]),coordinates:p.coordinates,precision:'area',demo:p.demo});}
 if(action==='development-activity'){const d=DEVELOPMENTS.find(d=>d.id===id);if(d)await mapExperience.openActivity({id:d.id,kind:'location',name:d.name,subtitle:d.area,image:d.image,coordinates:d.coordinates,precision:'area'});}
 if(action==='photo-next'||action==='photo-prev'){const track=target.closest('.gallery').querySelector('.photo-track');const index=Math.round(track.scrollLeft/track.clientWidth);const next=(index+(action==='photo-next'?1:-1)+track.children.length)%track.children.length;track.scrollTo({left:next*track.clientWidth,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
 if(action==='super-favorite'){const saved=!state.superFavorites.has(id);saved?state.superFavorites.add(id):state.superFavorites.delete(id);try{localStorage.setItem('nexus-link-super-favorites',JSON.stringify([...state.superFavorites]));}catch{}document.querySelectorAll('[data-action="super-favorite"]').forEach(button=>{if(button.dataset.id===id){button.setAttribute('aria-pressed',String(saved));button.setAttribute('aria-label',saved?'Remove super favorite':'Super favorite this home');}});mapExperience.updateShortlist();placesControl?.render();toast(saved?'Super favorite saved on this device.':'Super favorite removed.');}
 if(action==='favorite'){
  target.disabled=true;try{const saved=!state.favorites.has(id);await adapter.setFavorite(id,saved);saved?state.favorites.add(id):state.favorites.delete(id);updateHeader();document.querySelectorAll('[data-action="favorite"]').forEach(button=>{if(button.dataset.id!==id)return;button.classList.toggle('saved',saved);button.setAttribute('aria-pressed',String(saved));if(button.classList.contains('favorite-button'))button.setAttribute('aria-label',`${saved?'Unsave':'Save'} home`);else button.innerHTML=icon('heart')+(saved?'Saved to your homes':'Save this home');});toast(saved?(adapter.mode==='demo'?'Saved on this device.':'Home saved.'):'Home removed from your saved selection.');mapExperience.updateShortlist();placesControl?.render();if(location.hash==='#saved')await renderRoute();}catch(error){toast(error.message);}finally{target.disabled=false;}
 }
 if(action==='compare'){if(state.compare.has(id))state.compare.delete(id);else if(state.compare.size<3)state.compare.add(id);else {toast('Compare up to three homes at a time.');return;}document.querySelectorAll('[data-action="compare"]').forEach(b=>{if(b.dataset.id===id){b.setAttribute('aria-pressed',String(state.compare.has(id)));b.innerHTML=icon('compare')+(state.compare.has(id)?'Comparing':'Compare');}});$('.compare-tray')?.remove();$('#content').insertAdjacentHTML('beforeend',compareTray());mapExperience.renderSheet();}
 if(action==='clear-compare'){state.compare.clear();$('.compare-tray')?.remove();document.querySelectorAll('[data-action="compare"]').forEach(b=>{b.setAttribute('aria-pressed','false');b.innerHTML=icon('compare')+'Compare';});}
 if(action==='example-compare'){state.compare=new Set(['demo-sliema-01','demo-gzira-02']);location.hash='compare';}
 if(action==='open-map')await openMap();
 if(action==='property-map'){const p=state.currentProperty||state.displayProperties?.find(p=>p.id===id);if(p)await openMap({id:p.developmentId||p.id,kind:p.developmentId?'development':'property',coordinates:p.coordinates});}
 if(action==='development-map'){const d=DEVELOPMENTS.find(d=>d.id===id);if(d)await openMap({id:d.id,kind:'development',coordinates:d.coordinates});}
 if(action==='share-property'){
  const url=new URL(location.href);url.search='';url.hash=`property/${encodeURIComponent(id)}`;
  try{await navigator.clipboard.writeText(url.href);toast(adapter.mode==='demo'?'Demo property link copied. No profile or private locations included.':'Property link copied.');}catch{modal('Share this home',`<p>This link contains only the property identity.</p><label>Property link<input readonly value="${esc(url.href)}"></label>`);}
 }
 if(action==='excluded'){modal('Your requirements stay protected.',`<p>These demo homes were left out because a required detail did not match or could not be verified, or because wider inspiration is turned off.</p><div class="excluded-list">${(state.results?.excluded||[]).map(p=>`<div><strong>${esc(p.id.replace('demo-','').replace(/-/g,' '))}</strong><span>${p.reasons.map(c=>`${esc(c.label)}: ${c.met===null?'unverified':'does not meet your preference'}`).join('<br>')}</span></div>`).join('')}</div><a class="outline-button" href="#profile" data-action="close-modal">Edit my requirements</a>`);}
 if(action==='viewing'){
  target.disabled=true;try{const result=await adapter.getViewingSlots(id);state.viewingPropertyId=id;
   modal('A closer look at your next home.',result.connected===false?`<div class="connection-state">${icon('clock')}<h3>Viewings will open here.</h3><p>Live viewing slots and requests will be available when 2906 / ARGUS is connected. No request has been sent.</p><button class="outline-button" data-action="close-modal">Back to this home</button></div>`:result.slots?.length?`<p>Select a released viewing slot. Availability will be checked again when you request it.</p><div class="slot-list">${result.slots.map(s=>`<button class="outline-button" data-action="book-slot" data-id="${esc(id)}" data-slot="${esc(s.id)}">${esc(s.label||new Date(s.start).toLocaleString())}</button>`).join('')}</div><div id="booking-result" role="status"></div>`:'<p>No viewing slots are currently available. Please check again later.</p>');
  }catch(error){toast(error.message);}finally{target.disabled=false;}
 }
 if(action==='book-slot'){
  target.disabled=true;try{const result=await adapter.requestViewing(id,target.dataset.slot);$('#booking-result').textContent=result.status==='confirmed'?'Your viewing is confirmed.':result.status==='pending'?'Your request has been received. Confirmation is pending.':'The request is not confirmed. Please choose another slot or try again.';}catch(error){$('#booking-result').textContent=error.message;}finally{target.disabled=false;}
 }
}
